//! The Remedy theme set, shared by every Remedy app.
//!
//! - [`PALETTES`]: the twelve Remedy palettes (Dark Forest first, the default), including
//!   the deuteranopia, protanopia and tritanopia variants. They come from the same source
//!   every Remedy app's skins use, generated by `tools/gen_palettes.py`.
//! - [`PORTAL_PALETTES`], [`portal_theme`] and [`portal_sheet`]: Portal's own theme set (its gold default and
//!   its Azure, Skyline and Lagoon colourblind palettes), token for token as Portal's page.
//! - [`ThemeChoice`]: a palette by id, or `System`, which follows the platform between the
//!   Dark and Light palettes.
//! - [`high_contrast`]: a theme's high-contrast form, for the system setting.
//! - [`sheet`]: the style sheet for RemedyUI's widgets, built only from theme tokens, so a
//!   user's edits to a theme restyle every widget.
//! - [`to_tokens`] and [`from_tokens`]: themes as W3C design-tokens files, for a user's own
//!   themes and for apps mapping their skin formats.

mod palettes;
mod portal;
mod sheet;
mod tokens;

pub use palettes::{PALETTES, Palette};
pub use portal::{
    PORTAL_PAGE_CSS, PORTAL_PALETTES, PortalPalette, portal_page_layers, portal_sheet, portal_theme,
};
pub use sheet::sheet;
pub use tokens::{TokenError, from_tokens, to_tokens};

use remedy_ui_core::Color;
use remedy_ui_core::style::Theme;

fn hex(s: &str) -> Color {
    Color::from_hex(s).unwrap_or(Color::BLACK)
}

/// The theme for a palette, on the Remedy type scale, spacing and radii.
pub fn theme(p: &Palette) -> Theme {
    let mut t = Theme::dark_forest();
    t.name = p.name.to_owned();
    let c = &mut t.colors;
    c.bg = hex(p.bg);
    c.panel = hex(p.panel);
    c.card = hex(p.card);
    c.text = hex(p.text);
    c.muted = hex(p.muted);
    c.accent = hex(p.accent);
    c.on_accent = hex(p.text);
    c.danger = hex(p.danger);
    c.warn = hex(p.warn);
    c.ok = hex(p.ok);
    c.line = Some(hex(p.line));
    c.custom.insert("faint".into(), hex(p.faint));
    c.custom.insert("accent-hover".into(), hex(p.accent_hover));
    t
}

/// The palette with `id`.
pub fn palette(id: &str) -> Option<&'static Palette> {
    PALETTES.iter().find(|p| p.id == id)
}

/// Which theme the user chose.
#[derive(Clone, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum ThemeChoice {
    /// Follow the platform: the Dark palette when it prefers dark, Light otherwise.
    System,
    /// A palette by id.
    Palette(String),
}

impl Default for ThemeChoice {
    fn default() -> Self {
        ThemeChoice::Palette("forest".into())
    }
}

impl ThemeChoice {
    /// The theme to use, given whether the platform prefers dark (`None`: it does not say)
    /// and whether high contrast is on. An unknown id falls back to Dark Forest.
    pub fn resolve(&self, system_dark: Option<bool>, high: bool) -> Theme {
        let id = match self {
            ThemeChoice::System if system_dark == Some(false) => "light",
            ThemeChoice::System => "dark",
            ThemeChoice::Palette(id) => id.as_str(),
        };
        let p = palette(id).or_else(|| palette("forest"));
        let t = p.map_or_else(Theme::dark_forest, theme);
        if high { high_contrast(&t) } else { t }
    }
}

/// `t` with high contrast: full-strength text everywhere, borders as strong as text, and
/// panels flattened toward the background, as platforms' high-contrast modes do.
pub fn high_contrast(t: &Theme) -> Theme {
    let mut h = t.clone();
    h.name = format!("{} (high contrast)", t.name);
    let c = &mut h.colors;
    c.muted = c.text;
    c.line = Some(c.text);
    c.panel = c.bg;
    c.card = c.bg.mix_oklab(c.text, 0.06);
    h.stroke = t.stroke.max(1.0) * 2.0;
    h
}

/// Every palette as a theme.
pub fn all() -> Vec<Theme> {
    PALETTES.iter().map(theme).collect()
}
